WITH days AS (
 SELECT 'META' platform,coalesce(connection_id::text,'LEGACY_UNBOUND') scope_key,metric_date::text business_date,count(*) source_rows FROM meta_ads.meta_adset_daily_metrics WHERE is_current AND metric_date<=DATE '2026-10-29' GROUP BY connection_id,metric_date
 UNION ALL SELECT 'CAFE24',coalesce(connection_id::text,'LEGACY_UNBOUND'),order_date::text,count(*) FROM meta_ads.cafe24_order_lines WHERE is_current AND order_date<=DATE '2026-10-29' GROUP BY connection_id,order_date
 UNION ALL SELECT 'GOOGLE',connection_id::text,metric_date::text,count(*) FROM meta_ads.google_campaign_daily_costs WHERE is_current AND metric_date<=DATE '2026-10-29' GROUP BY connection_id,metric_date
 UNION ALL SELECT 'COUPANG','LEGACY_COUPANG_SINGLE_UPLOAD',sale_date::text,count(*) FROM meta_ads.coupang_sale_lines l JOIN meta_ads.coupang_upload_batches b ON b.id=l.upload_batch_id WHERE l.is_current AND b.status::text='IMPORTED' AND sale_date<=DATE '2026-10-29' GROUP BY sale_date
 UNION ALL SELECT 'COUPANG','LEGACY_COUPANG_SINGLE_UPLOAD',metric_date::text,count(*) FROM meta_ads.coupang_ad_metrics a JOIN meta_ads.coupang_upload_batches b ON b.id=a.upload_batch_id WHERE a.is_current AND b.status::text='IMPORTED' AND metric_date<=DATE '2026-10-29' GROUP BY metric_date
 UNION ALL SELECT 'NAVER',payload->>'storeId',payload->>'paymentDate',count(*) FROM public.order_items WHERE payload->>'storeId' IN('5ba1d3cf-7aee-4cd1-aecd-d44352f665dd','78f8cb08-ffe3-481a-94d7-be87ae93ed79') AND payload->>'paymentDate' BETWEEN '2000-01-01' AND '2026-10-29' GROUP BY payload->>'storeId',payload->>'paymentDate'
 UNION ALL SELECT 'NAVER',payload->>'storeId',payload->>'reportDate',count(*) FROM public.ad_campaign_daily_costs WHERE payload->>'storeId' IN('5ba1d3cf-7aee-4cd1-aecd-d44352f665dd','78f8cb08-ffe3-481a-94d7-be87ae93ed79') AND payload->>'reportDate' BETWEEN '2000-01-01' AND '2026-10-29' GROUP BY payload->>'storeId',payload->>'reportDate'
)
SELECT jsonb_build_object('observedAt',now(),'days',(SELECT jsonb_agg(to_jsonb(d) ORDER BY platform,scope_key,business_date) FROM (SELECT platform,scope_key,business_date,sum(source_rows) source_rows FROM days GROUP BY platform,scope_key,business_date) d),'privacy','Scope/day counts only, no customer fields') AS inventory;
